@override
Widget build(BuildContext context) {
  return Animated(
    value: 1.2,
    curve: Curves.easeInOut,
    duration: Duration(milliseconds: 300),
    builder: (context, child, animation) => Transform.scale(
      scale: animation.value,
      child: child,
    ),
    child: Container(
      width: 40,
      height: 40,
      color: Colors.red,
    ),
  );
}
